1	/**
2	 * The `LOCALE_ID` an era build set from the command line and the new one does
3	 * not set at all.
4	 *
5	 * `--i18n-locale <value>` did two things on the pre-Ivy CLI: it told the
6	 * compiler which message bundle to substitute, and it bound the value into the
7	 * application's root injector as `LOCALE_ID`. The Angular CLI removed the flag
8	 * after the 12 line — the 13 browser builder schema declares no `i18nLocale`,
9	 * so the flag is dropped from the migrated command line by
10	 * `workspace-script-flags.ts` — and nothing on the new line puts the value back.
11	 * `LOCALE_ID` then resolves to the framework's own default, `en-US`, and the
12	 * application is running under a locale it was never built for.
13	 *
14	 * **This defect emits nothing at build time.** The measured case is pigallery2:
15	 * its own module wires
16	 * `{provide: TRANSLATIONS, useFactory: translationsFactory, deps: [LOCALE_ID]}`
17	 * and the factory guards on `locale === 'en'` exactly, so with `LOCALE_ID` at
18	 * `en-US` it fell through to a `require` for a translation file that has never
19	 * existed and threw `Cannot find module './messages.en-US.xlf'` in the browser,
20	 * before the gallery mounted. The build that produced it reported zero errors
21	 * and zero warnings. Every other reader of `LOCALE_ID` — `DatePipe`,
22	 * `CurrencyPipe`, `DecimalPipe`, `registerLocaleData` lookups — fails more
23	 * quietly than that: it formats against the wrong locale and says nothing.
24	 *
25	 * The fix is the injector, because the injector is the only place the new line
26	 * offers: `{provide: LOCALE_ID, useValue: '<value>'}` in the root module's
27	 * providers. That is a *translation of a removed flag*, a sibling of the flag
28	 * rewriting in `workspace-script-flags.ts`, and it is only that.
29	 *
30	 * ## What is read, and what is never invented
31	 *
32	 * The locale is **supplied, never derived**. This capability takes an
33	 * {@link EraLocaleReading} — a value somebody read out of the era build's own
34	 * argv — and with no reading supplied it stands down and writes nothing. It
35	 * does not default to `en`, does not read a locale off the cell, does not infer
36	 * one from the application's translation files, and does not consult the host.
37	 * A locale nobody measured is a claim about what the application was built for,
38	 * and the whole defect above is what happens when that claim is wrong.
39	 *
40	 * `readEraLocaleFlagValue` is the reading for a script-driven build: it parses
41	 * `--i18n-locale en` or `--i18n-locale=en` out of the span
42	 * `workspace-script-flags.ts` already captures for the flag it removed, so the
43	 * value the migration deleted from the command line is the value it writes into
44	 * the injector. A build driven by something other than an `ng` script — a gulp
45	 * task, a shell wrapper — is read by whoever can read it, and hands the value
46	 * in as an {@link EraLocaleReading} of its own.
47	 *
48	 * ## Where it is written
49	 *
50	 * - **The module that bootstraps.** `LOCALE_ID` belongs to the root injector,
51	 *   and the root injector is the one the bootstrapped module configures. The
52	 *   site is therefore an `@NgModule` literal with a non-empty `bootstrap` array,
53	 *   resolved through the module's own binding for `NgModule`. A feature module
54	 *   is not a site: providing a locale there would move the value into a lazy
55	 *   injector and change which components see it.
56	 * - **First in the array, deliberately.** Angular resolves a duplicated token to
57	 *   the *last* provider for it, so a provider written first loses to any
58	 *   provider the module reaches later — including one inside a spread or a
59	 *   provider array this reading cannot open. Writing first is what makes the
60	 *   edit unable to overrule a decision the application already made.
61	 * - **Once.** A module that already carries a `provide: LOCALE_ID` property
62	 *   anywhere in the file is left exactly as it is, whatever the provider's value
63	 *   expression is. The check is detection, not overwrite: a locale somebody
64	 *   chose outranks a locale this capability read.
65	 *
66	 * The token is spelled as the module already spells it — an existing named
67	 * import is reused under its own local name, a namespace import is written
68	 * through, and only a module that imports `@angular/core` without `LOCALE_ID`
69	 * has its existing declaration extended. A second `@angular/core` declaration is
70	 * a shape the application did not write. In the measured pigallery2 module no
71	 * import was added at all, because `LOCALE_ID` was already imported as the
72	 * `deps` of the application's own `TRANSLATIONS` provider.
73	 *
74	 * ## Nonclaims
75	 *
76	 * - The reading is one module. A `LOCALE_ID` supplied from another file — a
77	 *   provider array this module imports by name, or a `bootstrapModule`
78	 *   options object — is not visible here. The first-position rule is what keeps
79	 *   that from becoming an override; it does not make it visible.
80	 * - Nothing here loads a translation, registers locale data, or declares
81	 *   `@angular/localize`. It supplies one value to one token. An application
82	 *   whose locale needs `registerLocaleData` still needs it, and the `$localize`
83	 *   runtime is a different capability's question.
84	 * - The value is data, not vocabulary. No locale tag is validated, ranked or
85	 *   canonicalised; the only rule applied to it is that it be a single argv token
86	 *   writable verbatim inside a source string literal, because a value that has
87	 *   to be escaped to be written is not the value that was read.
88	 */
89	
90	import { compareStrings, majorOf, type AngularTargetCell } from './angular-target-cell.ts';
91	import {
92		applySourceEdits,
93		denotesExport,
94		forEachNode,
95		isFreeRootName,
96		lineOf,
97		namedSpecifiersOf,
98		parseModule,
99		plainProperties,
100		readModuleImports,
101		type AstNode,
102		type ModuleImports,
103		type PlainProperty,
104		type SemanticModule,
105		type SourceEdit,
106	} from './semantic-module.ts';
107	
108	const CAPABILITY = 'Locale id provider';
109	
110	/** The package that publishes both symbols this capability resolves against. */
111	export const LOCALE_ID_PACKAGE = '@angular/core';
112	
113	/** The token the era flag used to bind, and the decorator that names a module. */
114	export const LOCALE_ID_TOKEN = 'LOCALE_ID';
115	const MODULE_DECORATOR = 'NgModule';
116	
117	/** The module-literal properties this capability reads. */
118	const BOOTSTRAP_PROPERTY = 'bootstrap';
119	const PROVIDERS_PROPERTY = 'providers';
120	
121	/** The removed flag whose value this capability translates into the injector. */
122	export const ERA_LOCALE_FLAG = '--i18n-locale';
123	
124	/**
125	 * The last Angular CLI major that parsed {@link ERA_LOCALE_FLAG}. A cell on that
126	 * major or below still accepts the flag, so the value still reaches the injector
127	 * the way it always did and there is nothing here to supply. The number is the
128	 * same reading `REMOVED_ANGULAR_CLI_FLAGS` carries for the flag, and a test pins
129	 * the two together rather than leaving them to drift.
130	 */
131	export const ERA_LOCALE_FLAG_REMOVED_AFTER_MAJOR = 12;
132	
133	/** A locale value somebody read out of an era build, and where they read it. */
134	export type EraLocaleReading = Readonly<{
135		/** The value the era build's own argv carried, verbatim. */
136		locale: string;
137		/** Where the reading was taken, in the reader's own words. */
138		readFrom: string;
139	}>;
140	
141	export type LocaleIdProviderChange = Readonly<{
142		kind: 'locale-id-provider';
143		/** The line the `@NgModule` decorator opens on. */
144		line: number;
145		/** The bootstrapping module the provider was written into. */
146		moduleClass: string;
147		/** The value written, exactly as it was read. */
148		locale: string;
149		/** Where the value was read, carried through from the reading. */
150		readFrom: string;
151		/** The provider, as written into the source. */
152		provider: string;
153		/** Whether an `@angular/core` import declaration was extended. */
154		importExtended: boolean;
155		/** Whether the module literal had no `providers` property before this. */
156		providersPropertyAdded: boolean;
157	}>;
158	
159	export type LocaleIdProviderMigration = Readonly<{
160		path: string;
161		source: string;
162		changed: boolean;
163		changes: readonly LocaleIdProviderChange[];
164		unhandled: readonly string[];
165	}>;
166	
167	/**
168	 * Whether a value can be written into a single-quoted string literal as itself.
169	 *
170	 * This is a rule about writing, not about locales: a quote, a backslash, a line
171	 * terminator or a control character would have to be escaped, and an escaped
172	 * value is no longer the value that was read. Whitespace is excluded for the
173	 * same reason — the reading is one argv token, and a token with a space in it
174	 * did not come from one.
175	 */
176	export function isWritableLocaleValue(value: string): boolean {
177		if (value === '') return false;
178		for (const character of value) {
179			const code = character.codePointAt(0) ?? 0;
180			if (code < 0x20 || code === 0x7f) return false;
181			if (character === "'" || character === '\\') return false;
182			if (/\s/u.test(character)) return false;
183		}
184		return true;
185	}
186	
187	/**
188	 * The value `--i18n-locale` carried in one captured argv span, or null.
189	 *
190	 * Both spellings the CLI accepted are read — `--i18n-locale en` and
191	 * `--i18n-locale=en` — because `workspace-script-flags.ts` captures the span the
192	 * era script actually wrote rather than a normalised form of it. Anything else,
193	 * including the flag with no value after it, is null: a flag whose value cannot
194	 * be read is not a reading of one.
195	 */
196	export function readEraLocaleFlagValue(span: string): string | null {
197		const trimmed = span.trim();
198		if (!trimmed.startsWith(ERA_LOCALE_FLAG)) return null;
199		const rest = trimmed.slice(ERA_LOCALE_FLAG.length);
200		if (rest === '') return null;
201		const separator = rest[0];
202		if (separator !== '=' && !/\s/u.test(separator ?? '')) return null;
203		const value = rest.slice(1).trim();
204		if (value === '' || /\s/u.test(value)) return null;
205		return value;
206	}
207	
208	/**
209	 * The reading a removed-flag change record states, or null when that record is
210	 * about some other flag.
211	 *
212	 * The argument is structural rather than the `ScriptFlagChange` type itself, so
213	 * that reading a command line and rewriting one stay two separate concerns with
214	 * no dependency between their modules.
215	 */
216	export function eraLocaleReadingOfRemovedFlag(
217		change: Readonly<{ script: string; from: string }>,
218	): EraLocaleReading | null {
219		const locale = readEraLocaleFlagValue(change.from);
220		if (locale === null) return null;
221		return Object.freeze({
222			locale,
223			readFrom: `the era build script \`${change.script}\` passed \`${change.from.trim()}\``,
224		});
225	}
226	
227	/** The provider, spelled as the measured migration spelled it. */
228	export function localeIdProviderSource(token: string, locale: string): string {
229		return `{provide: ${token}, useValue: '${locale}'}`;
230	}
231	
232	/** The static name of a non-computed property key, or null for anything else. */
233	function propertyName(key: AstNode): string | null {
234		if (key.type === 'Identifier') return key.name;
235		if (key.type === 'Literal' && typeof key.value === 'string') return key.value;
236		return null;
237	}
238	
239	/**
240	 * Whether this module already provides `LOCALE_ID`, anywhere in the file.
241	 *
242	 * The scan is the whole module rather than the one providers array, because a
243	 * provider list is routinely assembled in a `const` beside the module and spread
244	 * into it, and a second provider written next to one somebody already wrote is
245	 * exactly the overwrite this capability refuses. `deps: [LOCALE_ID]` is not a
246	 * match: reading the token is what makes the missing provider a defect.
247	 */
248	export function modulesProvideLocaleId(module: SemanticModule, core: ModuleImports): boolean {
249		let provided = false;
250		forEachNode(module.ast, (node) => {
251			if (provided || node.type !== 'ObjectExpression') return;
252			for (const property of node.properties) {
253				if (property.type !== 'Property') continue;
254				if (property.kind !== 'init' || property.computed) continue;
255				if (propertyName(property.key) !== 'provide') continue;
256				if (denotesExport(module, property.value, core, LOCALE_ID_TOKEN)) provided = true;
257			}
258		});
259		return provided;
260	}
261	
262	/** How this module spells `LOCALE_ID`, and the import edit that makes it true. */
263	type TokenSpelling = Readonly<{ token: string; edit: SourceEdit | null; extended: boolean }>;
264	
265	type ImportDeclarationNode = Extract<AstNode, { type: 'ImportDeclaration' }>;
266	
267	/** Every `@angular/core` import declaration, in source order. */
268	function coreDeclarations(module: SemanticModule): readonly ImportDeclarationNode[] {
269		const declarations: ImportDeclarationNode[] = [];
270		for (const node of module.ast.body)
271			if (node.type === 'ImportDeclaration' && node.source.value === LOCALE_ID_PACKAGE)
272				declarations.push(node);
273		return declarations;
274	}
275	
276	/**
277	 * The name the module already binds the token under, or the edit that binds it.
278	 *
279	 * An alias is honoured because the binding is what resolves, not the spelling; a
280	 * namespace import is written through rather than joined by a named one; and a
281	 * module that imports the package some other way has its first declaration
282	 * extended. A module whose root scope already binds `LOCALE_ID` to something
283	 * else gets nothing: introducing a second meaning for a name in one scope is not
284	 * an edit this capability is entitled to make.
285	 */
286	function tokenSpelling(module: SemanticModule, core: ModuleImports): TokenSpelling | null {
287		const declarations = coreDeclarations(module);
288		for (const declaration of declarations)
289			for (const specifier of declaration.specifiers) {
290				if (specifier.type !== 'ImportSpecifier') continue;
291				const imported = specifier.imported;
292				if (imported.type !== 'Identifier' || imported.name !== LOCALE_ID_TOKEN) continue;
293				return Object.freeze({ token: specifier.local.name, edit: null, extended: false });
294			}
295		for (const declaration of declarations)
296			for (const specifier of declaration.specifiers) {
297				if (specifier.type !== 'ImportNamespaceSpecifier') continue;
298				return Object.freeze({
299					token: `${specifier.local.name}.${LOCALE_ID_TOKEN}`,
300					edit: null,
301					extended: false,
302				});
303			}
304		if (core.namespace !== null) return null;
305		if (!isFreeRootName(module, LOCALE_ID_TOKEN)) return null;
306		for (const declaration of declarations) {
307			const last = namedSpecifiersOf(declaration).at(-1);
308			if (last === undefined) continue;
309			return Object.freeze({
310				token: LOCALE_ID_TOKEN,
311				edit: { start: last.end, end: last.end, text: `, ${LOCALE_ID_TOKEN}` },
312				extended: true,
313			});
314		}
315		return null;
316	}
317	
318	/** The indentation of the line `node` starts on, when it starts that line. */
319	function ownLineIndent(source: string, node: AstNode): string | null {
320		const lineStart = source.lastIndexOf('\n', node.start - 1) + 1;
321		const before = source.slice(lineStart, node.start);
322		return before.trim() === '' ? before : null;
323	}
324	
325	/**
326	 * Write `text` as the first element of an array literal.
327	 *
328	 * A literal whose elements own their lines keeps that shape; an inline literal
329	 * stays inline. Neither form is reflowed: the edit is one provider, and a
330	 * capability that also reformatted the array around it would report a change
331	 * larger than the one it made.
332	 */
333	function insertFirstElement(
334		source: string,
335		array: Extract<AstNode, { type: 'ArrayExpression' }>,
336		text: string,
337	): SourceEdit {
338		const first = array.elements.find((element) => element !== null && element !== undefined);
339		if (first === undefined || first === null)
340			return Object.freeze({ start: array.start + 1, end: array.start + 1, text });
341		const indent = ownLineIndent(source, first);
342		return Object.freeze({
343			start: first.start,
344			end: first.start,
345			text: indent === null ? `${text}, ` : `${text},\n${indent}`,
346		});
347	}
348	
349	/** Write `text` as the last property of an object literal that has properties. */
350	function appendProperty(
351		source: string,
352		properties: readonly PlainProperty[],
353		text: string,
354	): SourceEdit | null {
355		const last = properties.at(-1);
356		if (last === undefined) return null;
357		const indent = ownLineIndent(source, last.node);
358		return Object.freeze({
359			start: last.node.end,
360			end: last.node.end,
361			text: indent === null ? `, ${text}` : `,\n${indent}${text}`,
362		});
363	}
364	
365	/** The name of the class a decorator sits on, for the change record. */
366	function decoratedClassName(module: SemanticModule, decorator: AstNode): string {
367		const owner = module.parentOf(decorator);
368		if (owner === null) return '<anonymous>';
369		if (owner.type !== 'ClassDeclaration' && owner.type !== 'ClassExpression') return '<anonymous>';
370		const id = owner.id;
371		if (id === null || id === undefined || id.type !== 'Identifier') return '<anonymous>';
372		return id.name;
373	}
374	
375	/** One bootstrapping `@NgModule` literal, as read. */
376	type BootstrapSite = Readonly<{
377		decorator: AstNode;
378		literal: AstNode;
379		properties: readonly PlainProperty[];
380	}>;
381	
382	/**
383	 * Supply the root injector the `LOCALE_ID` the era build's command line used to
384	 * supply, and only where a reading of that command line says what it was.
385	 */
386	export function provideEraLocaleId(
387		path: string,
388		source: string,
389		reading: EraLocaleReading | null,
390		cell: AngularTargetCell,
391	): LocaleIdProviderMigration {
392		const unchanged = (unhandled: readonly string[]): LocaleIdProviderMigration =>
393			Object.freeze({
394				path,
395				source,
396				changed: false,
397				changes: Object.freeze([]),
398				unhandled: Object.freeze([...new Set(unhandled)].sort(compareStrings)),
399			});
400		if (reading === null) return unchanged([]);
401		const major = majorOf(cell.angularLine);
402		if (major === null || major <= ERA_LOCALE_FLAG_REMOVED_AFTER_MAJOR) return unchanged([]);
403		if (!isWritableLocaleValue(reading.locale))
404			return unchanged([
405				`${path}: the supplied locale reading (${reading.readFrom}) is not a single argv token ` +
406					'that can be written into a source string literal as itself, so no provider was ' +
407					'written; a locale that has to be escaped to be written is not the locale that was read',
408			]);
409		const module = parseModule(CAPABILITY, path, source);
410		const core = readModuleImports(module, LOCALE_ID_PACKAGE);
411		if (!core.present) return unchanged([]);
412		if (modulesProvideLocaleId(module, core)) return unchanged([]);
413		const sites: BootstrapSite[] = [];
414		const unhandled: string[] = [];
415		forEachNode(module.ast, (node) => {
416			if (node.type !== 'Decorator') return;
417			const call = node.expression;
418			if (call.type !== 'CallExpression') return;
419			if (!denotesExport(module, call.callee, core, MODULE_DECORATOR)) return;
420			const literal = call.arguments[0];
421			if (literal === undefined || literal.type !== 'ObjectExpression') return;
422			const line = lineOf(source, node.start);
423			const properties = plainProperties(literal);
424			if (properties === null) {
425				unhandled.push(
426					`${path} line ${String(line)}: the @${MODULE_DECORATOR} literal carries a spread, a ` +
427						'computed key or an accessor, so whether it bootstraps and what it already provides ' +
428						'cannot be read from it, and it was left exactly as it is',
429				);
430				return;
431			}
432			const bootstrap = properties.find((property) => property.name === BOOTSTRAP_PROPERTY);
433			if (bootstrap === undefined) return;
434			if (bootstrap.value.type !== 'ArrayExpression' || bootstrap.value.elements.length === 0) return;
435			sites.push(Object.freeze({ decorator: node, literal, properties }));
436		});
437		if (sites.length === 0) return unchanged(unhandled);
438		if (sites.length > 1) {
439			const lines = sites.map((site) => String(lineOf(source, site.decorator.start)));
440			return unchanged([
441				...unhandled,
442				`${path}: ${String(sites.length)} @${MODULE_DECORATOR} literals in this module bootstrap a ` +
443					`component (lines ${lines.join(', ')}), so which of them configures the root injector ` +
444					'this application starts with is not something the module states, and no provider was ' +
445					'written into either',
446			]);
447		}
448		const site = sites[0] as BootstrapSite;
449		const line = lineOf(source, site.decorator.start);
450		const spelling = tokenSpelling(module, core);
451		if (spelling === null)
452			return unchanged([
453				...unhandled,
454				`${path} line ${String(line)}: ${LOCALE_ID_TOKEN} is not imported from ` +
455					`${LOCALE_ID_PACKAGE} here and this module offers nowhere to write the import that ` +
456					'would not either bind a name its own scope already uses or add a second declaration ' +
457					`of ${LOCALE_ID_PACKAGE}, so no provider was written`,
458			]);
459		const provider = localeIdProviderSource(spelling.token, reading.locale);
460		const providers = site.properties.find((property) => property.name === PROVIDERS_PROPERTY);
461		const edits: SourceEdit[] = [];
462		let providersPropertyAdded = false;
463		if (providers === undefined) {
464			const appended = appendProperty(
465				source,
466				site.properties,
467				`${PROVIDERS_PROPERTY}: [${provider}]`,
468			);
469			if (appended === null) return unchanged(unhandled);
470			edits.push(appended);
471			providersPropertyAdded = true;
472		} else if (providers.value.type === 'ArrayExpression') {
473			edits.push(insertFirstElement(source, providers.value, provider));
474		} else {
475			return unchanged([
476				...unhandled,
477				`${path} line ${String(line)}: ${PROVIDERS_PROPERTY} is not an array literal, so there is ` +
478					'no position in it this capability can read, and it was left exactly as it is',
479			]);
480		}
481		if (spelling.edit !== null) edits.push(spelling.edit);
482		const migrated = applySourceEdits(source, edits);
483		return Object.freeze({
484			path,
485			source: migrated,
486			changed: migrated !== source,
487			changes: Object.freeze([
488				Object.freeze({
489					kind: 'locale-id-provider' as const,
490					line,
491					moduleClass: decoratedClassName(module, site.decorator),
492					locale: reading.locale,
493					readFrom: reading.readFrom,
494					provider,
495					importExtended: spelling.extended,
496					providersPropertyAdded,
497				}),
498			]),
499			unhandled: Object.freeze([...new Set(unhandled)].sort(compareStrings)),
500		});
501	}
