47	
48	/** The entry point the package publishes for the pre-`main` position. */
49	export const LOCALIZE_POLYFILL_ENTRY_POINT = '@angular/localize/init' as const;
50	
51	/**
52	 * The first Angular line whose compiler emits `$localize` tagged templates for
53	 * i18n-marked templates instead of substituting translations at compile time.
54	 */
55	export const LOCALIZE_EMITTING_ANGULAR_MAJOR = 9;
56	
57	/** One i18n marker an application's own template carries. */
58	export type TemplateI18nMarker = Readonly<{
59		/** The template the marker was read from. */
60		template: string;
61		/** The 1-based line the marked element opens on. */
62		line: number;
63		/** The element the marker sits on. */
64		element: string;
65		/** The marker attribute exactly as the template spells it. */
66		attribute: string;
67	}>;
68	
69	/** What an application's templates say about i18n, as read. */
70	export type TemplateI18nReading = Readonly<{
71		/** Every marker found, template order then line order. */
72		markers: readonly TemplateI18nMarker[];
73		/** The templates that carry at least one marker. */
74		markedTemplates: readonly string[];
75		/** Every template read, marked or not. */
76		templatesRead: number;
77	}>;
78	
79	/** Whether one attribute name is one of Angular's i18n markers. */
80	export function isI18nMarkerAttribute(name: string): boolean {
81		return name === 'i18n' || name.startsWith('i18n-');
82	}
83	
84	/**
85	 * Read every i18n marker an application's templates carry.
86	 *
87	 * The reading is the compiler's own parse rather than a text search: `i18n` is
88	 * an attribute of an element, and an attribute is a thing the template parser
89	 * knows about while a substring is a thing that can sit inside a comment, a
90	 * string or an unrelated word.
91	 */
92	export function readTemplateI18nMarkers(
93		templates: readonly AngularTemplateSource[],
94	): TemplateI18nReading {
95		const markers: TemplateI18nMarker[] = [];
96		const marked: string[] = [];
97		const analyses = analyzeAngularTemplates(templates);
98		for (const analysis of analyses) {
99			const before = markers.length;
100			for (const marker of analysis.i18nMarkers) {
101				if (!isI18nMarkerAttribute(marker.marker)) continue;
102				markers.push(
103					Object.freeze({
104						template: analysis.path,
105						line: marker.line,
106						element: marker.element,
107						attribute: marker.marker,
108					}),
109				);
110			}
111			if (markers.length > before) marked.push(analysis.path);
112		}
113		return Object.freeze({
114			markers: Object.freeze(markers),
115			markedTemplates: Object.freeze(marked),
116			templatesRead: analyses.length,
117		});
118	}
119	
120	/** One dependency the declaration writes into the application's manifest. */
121	export type LocalizeDependencyChange = Readonly<{
122		field: 'dependencies';
123		name: typeof LOCALIZE_PACKAGE;
124		from: string | null;
125		to: string;
126	}>;
127	
128	export type TemplateI18nRuntimeDeclaration = Readonly<{
129		/** Whether the package was declared. */
130		declared: boolean;
131		/** The manifest source, rewritten only when something changed. */
132		manifest: string;
133		/** The dependency change written, or null when none was. */
134		change: LocalizeDependencyChange | null;
135		/** The polyfill entry point to declare, or null when nothing is declared. */
136		entryPoint: typeof LOCALIZE_POLYFILL_ENTRY_POINT | null;
137		/** The reading the decision rests on. */
138		reading: TemplateI18nReading;
139		/** What declaring this changes about the application, stated. */
140		declaredDifferences: readonly string[];
141		/** Everything refused, by name and with its reason. */
142		unhandled: readonly string[];
143	}>;
144	
145	function refusal(
146		manifest: string,
147		reading: TemplateI18nReading,
148		why: string,
149	): TemplateI18nRuntimeDeclaration {
150		return Object.freeze({
151			declared: false,
152			manifest,
153			change: null,
154			entryPoint: null,
155			reading,
156			declaredDifferences: Object.freeze([]),
157			unhandled: Object.freeze([why]),
158		});
159	}
160	
161	/**
162	 * Declare the `$localize` runtime for an application whose templates ask for it
163	 * on a line whose compiler emits it.
164	 *
165	 * The manifest half is all this returns for the workspace: the entry point is
166	 * handed back by name for the caller to declare through
167	 * {@link declarePolyfillEntryPoint}, which is the one place in this package that
168	 * knows which builder targets take a `polyfills` option and what to do with a
169	 * target whose option is in the pre-v15 string form.
170	 */
171	export function declareTemplateI18nRuntime(input: {
172		manifest: string;
173		templates: readonly AngularTemplateSource[];
174		cell: AngularTargetCell;
175	}): TemplateI18nRuntimeDeclaration {
176		const reading = readTemplateI18nMarkers(input.templates);
177		if (reading.markers.length === 0)
178			return refusal(
179				input.manifest,
180				reading,
181				`${LOCALIZE_PACKAGE} was not declared: none of the ${String(reading.templatesRead)} ` +
182					'templates read carries an `i18n` or `i18n-<attribute>` marker, so this application ' +
183					'compiles to no `$localize` tagged template and a runtime for one would be a ' +
184					'polyfill nothing in the bundle asks for',
185			);
186		const major = majorOf(input.cell.angularLine);
187		if (major === null || major < LOCALIZE_EMITTING_ANGULAR_MAJOR)
188			return refusal(
189				input.manifest,
190				reading,
191				`${LOCALIZE_PACKAGE} was not declared: the declared cell is on Angular ` +
192					`${input.cell.angularLine}, whose compiler substitutes translations into the ` +
193					'factories it emits rather than emitting `$localize` tagged templates, so the ' +
194					'marked templates reference no runtime global on this line',
195			);
196		const range = alignedVersionRange(LOCALIZE_PACKAGE, input.cell);
197		if (range === null)
198			return refusal(
199				input.manifest,
200				reading,
201				`${LOCALIZE_PACKAGE} was not declared: the declared cell ${input.cell.id} carries no ` +
202					'range for it and none for the `@angular/` family, and picking a version for a ' +
203					'framework package is the cell\'s decision rather than this capability\'s',
204			);
205		const parsed = parseStrictJson(input.manifest, 'template i18n runtime');
206		const dependencies = objectAt(parsed['dependencies']);
207		if (dependencies === null)
208			return refusal(
209				input.manifest,
210				reading,
211				`${LOCALIZE_PACKAGE} was not declared: the application manifest carries no ` +
212					'`dependencies` object, so there is nothing here this capability can read as the ' +
213					'declared closure it would be adding to',
214			);
215		const current = dependencies[LOCALIZE_PACKAGE];
216		if (current !== undefined && typeof current !== 'string')
217			return refusal(
218				input.manifest,
219				reading,
220				`${LOCALIZE_PACKAGE} was not declared: the manifest already carries it as something ` +
221					'other than a version range, and overwriting a declaration this capability cannot ' +
222					'read would discard a decision somebody else made',
223			);
224		const declaredDifferences = [
225			`globalThis.$localize exists in this application's browser context where it did not ` +
226				`before. ${LOCALIZE_PACKAGE} is declared at ${range} and its published ` +
227				`\`${LOCALIZE_POLYFILL_ENTRY_POINT}\` entry point installs the runtime before \`main\`, ` +
228				`because ${String(reading.markers.length)} i18n markers across ` +
229				`${String(reading.markedTemplates.length)} of this application's ` +
230				`${String(reading.templatesRead)} templates compile to \`$localize\` tagged templates ` +
231				`on Angular ${input.cell.angularLine}. With no translations loaded the runtime ` +
232				'evaluates each tag to its source message, which is the text the template already ' +
233				'carries — the application renders its own strings, not translated ones, and this ' +
234				'capability loads no locale.',
235		];
236		if (current === range)
237			return Object.freeze({
238				declared: true,
239				manifest: input.manifest,
240				change: null,
241				entryPoint: LOCALIZE_POLYFILL_ENTRY_POINT,
242				reading,
243				declaredDifferences: Object.freeze(declaredDifferences),
244				unhandled: Object.freeze([]),
245			});
246		const next: Record<string, string> = {};
247		for (const name of [...Object.keys(dependencies), LOCALIZE_PACKAGE].sort()) {
248			if (name === LOCALIZE_PACKAGE) {
249				next[name] = range;
250				continue;
251			}
252			const value = dependencies[name];
253			if (typeof value !== 'string')
254				return refusal(
255					input.manifest,
256					reading,
257					`${LOCALIZE_PACKAGE} was not declared: \`dependencies.${name}\` is not a version ` +
258						'range, so rewriting this manifest would rewrite a declaration this capability ' +
259						'cannot read',
260				);
261			next[name] = value;
262		}
263		return Object.freeze({
264			declared: true,
265			manifest: serializeJson({ ...parsed, dependencies: next }),
266			change: Object.freeze({
267				field: 'dependencies',
268				name: LOCALIZE_PACKAGE,
269				from: current ?? null,
270				to: range,
271			}),
272			entryPoint: LOCALIZE_POLYFILL_ENTRY_POINT,
273			reading,
274			declaredDifferences: Object.freeze(declaredDifferences),
275			unhandled: Object.freeze([]),
276		});
277	}
