				...aligned.changes.map(describeDependencyChange),
				...scripts.changes.map(describeScriptFlagChange),
				...declared.declarations.map(
					(entry) =>
						`added ${entry.field}.${entry.name} = ${entry.range} — ${entry.reason}`,
				),
